/**
 * Unicode character predicates that mirror the exact CPython helpers we depend on.
 *
 * Only the pieces that are observable through the behaviour of the original
 * program are modelled here:
 *
 *   - `isPySpace`   -> CPython's `Py_UNICODE_ISSPACE`, used by `int(str)` when it
 *                      strips surrounding whitespace.
 *   - `isPyPrintable` -> CPython's `str.isprintable()`, used by `repr(str)` to
 *                      decide whether a character must be escaped.
 *   - `decimalDigitValue` -> the numeric value of a `Nd` (decimal digit)
 *                      character, used by `int(str)` which accepts any Unicode
 *                      decimal digit, not just ASCII `0-9`.
 */

/**
 * `Py_UNICODE_ISSPACE` is defined as:
 *
 *     ch < 128 ? Py_ISSPACE(ch) : _PyUnicode_IsWhitespace(ch)
 *
 * `Py_ISSPACE` only covers `\t\n\v\f\r` and the plain space, which is why
 * `int('\x1c5')` raises even though `'\x1c'.isspace()` is true. Above the ASCII
 * range the generated Unicode whitespace table applies.
 */
const ASCII_SPACE = new Set([0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20]);

const NON_ASCII_SPACE = new Set([
  0x85, 0xa0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

/** @param {number} cp code point */
export function isPySpace(cp) {
  return cp < 128 ? ASCII_SPACE.has(cp) : NON_ASCII_SPACE.has(cp);
}

/**
 * `str.isprintable()` is false for the categories Cc, Cf, Cs, Co, Cn, Zl, Zp and
 * Zs -- with the single exception of U+0020, which Python considers printable.
 */
const NON_PRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

/** @param {number} cp code point */
export function isPyPrintable(cp) {
  if (cp === 0x20) return true;
  return !NON_PRINTABLE.test(String.fromCodePoint(cp));
}

const IS_ND = /^\p{Nd}$/u;

/**
 * Unicode guarantees that every decimal digit set is ten consecutive code
 * points ordered 0..9, so the value of a digit is its offset from the start of
 * the contiguous `Nd` run, modulo ten. Taking the modulo matters because a few
 * runs hold several digit sets back to back (e.g. the mathematical digits at
 * U+1D7CE..U+1D7FF).
 *
 * @param {number} cp code point
 * @returns {number} 0..9, or -1 when `cp` is not a decimal digit
 */
const digitValueCache = new Map();

export function decimalDigitValue(cp) {
  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30;
  const cached = digitValueCache.get(cp);
  if (cached !== undefined) return cached;

  let value = -1;
  if (IS_ND.test(String.fromCodePoint(cp))) {
    let start = cp;
    // Runs are short; the bound is only a guard against pathological input.
    for (let steps = 0; steps < 1024 && start > 0; steps += 1) {
      if (!IS_ND.test(String.fromCodePoint(start - 1))) break;
      start -= 1;
    }
    value = (cp - start) % 10;
  }
  digitValueCache.set(cp, value);
  return value;
}

