/**
 * `int(str)` semantics, producing a `BigInt` so that Python's arbitrary
 * precision integers survive the port unchanged.
 */

import { isPySpace, decimalDigitValue } from './unicode_tables.mjs';

/** Raised for the same inputs that make CPython's `int()` raise `ValueError`. */
export class PyValueError extends Error {}

/**
 * Convert a string to an integer exactly the way `int(text)` does for base 10:
 *
 *   - surrounding Unicode whitespace is stripped
 *   - an optional single `+` / `-` sign may follow, with no space after it
 *   - the remainder must be one or more Unicode decimal digits, optionally
 *     separated by single underscores that sit strictly between digits
 *
 * @param {string} text
 * @returns {bigint}
 */
export function pyInt(text) {
  const chars = Array.from(text);

  let start = 0;
  let end = chars.length;
  while (start < end && isPySpace(chars[start].codePointAt(0))) start += 1;
  while (end > start && isPySpace(chars[end - 1].codePointAt(0))) end -= 1;

  let negative = false;
  if (start < end && (chars[start] === '+' || chars[start] === '-')) {
    negative = chars[start] === '-';
    start += 1;
  }

  if (start >= end) throw new PyValueError('no digits');

  let digits = '';
  let previousWasDigit = false;
  for (let i = start; i < end; i += 1) {
    const ch = chars[i];
    if (ch === '_') {
      // Underscores are only legal as digit separators.
      if (!previousWasDigit || i + 1 >= end) throw new PyValueError('bad underscore');
      previousWasDigit = false;
      continue;
    }
    const value = decimalDigitValue(ch.codePointAt(0));
    if (value < 0) throw new PyValueError('not a digit');
    digits += String(value);
    previousWasDigit = true;
  }

  if (!previousWasDigit) throw new PyValueError('trailing underscore');

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

