/**
 * An insertion-ordered mapping with the iteration semantics of a Python `dict`.
 *
 * A plain JavaScript object cannot be used: it reorders integer-like keys, which
 * would silently change the order of `'10'` relative to `'9'`. `Map` preserves
 * insertion order for every key type, so it backs the implementation.
 */
export class PyDict {
  /** @param {Iterable<[string, unknown]>} [entries] */
  constructor(entries) {
    /** @type {Map<string, unknown>} */
    this._store = new Map(entries ?? []);
  }

  get size() {
    return this._store.size;
  }

  /** @param {string} key */
  has(key) {
    return this._store.has(key);
  }

  /** @param {string} key */
  get(key) {
    return this._store.get(key);
  }

  /**
   * @param {string} key
   * @param {unknown} value
   */
  set(key, value) {
    this._store.set(key, value);
    return this;
  }

  keys() {
    return this._store.keys();
  }

  values() {
    return this._store.values();
  }

  entries() {
    return this._store.entries();
  }

  [Symbol.iterator]() {
    return this._store.keys();
  }

  /**
   * The comprehension `{k: f(v) for k, v in self.items()}` -- key order is
   * inherited from the source dict.
   *
   * @param {(value: unknown, key: string) => unknown} fn
   */
  mapValues(fn) {
    const result = new PyDict();
    for (const [key, value] of this._store) result.set(key, fn(value, key));
    return result;
  }
}

/** `{str(i): f(i) for i in range(stop)}` for a non-negative `stop`. */
export function dictFromRange(stop, fn) {
  const result = new PyDict();
  for (let i = 0n; i < stop; i += 1n) result.set(i.toString(), fn(i));
  return result;
}

