import { pyInt, PyValueError } from '../python/int.mjs';
import { reprString } from '../python/repr.mjs';

const MAX_HELP_POSITION = 24;
const INDENT = 2;

/** `argparse._negative_number_matcher` */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** The registered `type=` callables, keyed by the `__name__` shown in errors. */
const TYPE_REGISTRY = {
  int: pyInt,
};

class Action {
  /**
   * @param {string[]} optionStrings
   * @param {{dest: string, type?: string, required?: boolean, nargs?: number, help?: string}} options
   */
  constructor(optionStrings, options) {
    this.optionStrings = optionStrings;
    this.dest = options.dest;
    this.type = options.type;
    this.required = options.required ?? false;
    this.nargs = options.nargs ?? 1;
    this.help = options.help ?? '';
    this.isHelpAction = options.dest === 'help';
  }

  /** `argparse._get_action_name` for an optional. */
  get name() {
    return this.optionStrings[0];
  }

  /** `HelpFormatter._format_action_invocation` for an optional. */
  formatInvocation() {
    if (this.nargs === 0) return this.optionStrings.join(', ');
    const metavar = this.dest.toUpperCase();
    return this.optionStrings.map((option) => `${option} ${metavar}`).join(', ');
  }

  /** The fragment this action contributes to the usage line. */
  formatUsage() {
    const option = this.optionStrings[0];
    const body = this.nargs === 0 ? option : `${option} ${this.dest.toUpperCase()}`;
    return this.required ? body : `[${body}]`;
  }
}

export class ArgumentParser {
  /** @param {{prog?: string}} [options] */
  constructor(options = {}) {
    this.prog = options.prog ?? defaultProg();
    /** @type {Action[]} */
    this.actions = [];
    /** @type {Map<string, Action>} */
    this.optionStringActions = new Map();
    this.actionMaxLength = 0;

    this.addArgument(['-h', '--help'], {
      dest: 'help',
      nargs: 0,
      help: 'show this help message and exit',
    });
  }

  /**
   * @param {string|string[]} optionStrings
   * @param {{type?: string, required?: boolean, dest?: string, nargs?: number, help?: string}} [options]
   */
  addArgument(optionStrings, options = {}) {
    const strings = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    const dest = options.dest ?? strings.find((s) => s.startsWith('--')).replace(/^--/, '').replace(/-/g, '_');
    const action = new Action(strings, { ...options, dest });

    this.actions.push(action);
    for (const optionString of strings) this.optionStringActions.set(optionString, action);

    // `add_argument` folds the current indent into the recorded width.
    this.actionMaxLength = Math.max(this.actionMaxLength, action.formatInvocation().length + INDENT);
    return action;
  }

