  formatUsage() {
    const parts = this.actions.map((action) => action.formatUsage());
    return `usage: ${[this.prog, ...parts].join(' ')}\n`;
  }

  /** The full `--help` text, including its trailing newline. */
  formatHelp() {
    const helpPosition = Math.min(this.actionMaxLength + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - INDENT - 2;
    const pad = ' '.repeat(INDENT);

    let out = this.formatUsage();
    out += '\n';
    out += 'options:\n';
    for (const action of this.actions) {
      const invocation = action.formatInvocation();
      if (!action.help) {
        out += `${pad}${invocation}\n`;
      } else if (invocation.length <= actionWidth) {
        out += `${pad}${invocation.padEnd(actionWidth)}  ${action.help}\n`;
      } else {
