  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  printHelp() {
    process.stdout.write(this.formatHelp());
    throw new SystemExit(0);
  }

  /**
   * Classify a token the way `argparse._parse_optional` does.
   *
   * @returns {{action: Action|null, optionString: string, explicitArg: string|null}|null}
   *   `null` means "this is not an optional", i.e. it may serve as a value.
   */
  _parseOptional(argString) {
    if (!argString) return null;
    if (argString[0] !== '-') return null;
    if (this.optionStringActions.has(argString)) {
