  _getOptionTuples(argString) {
    const result = [];
    if (argString.startsWith('--')) {
      const equals = argString.indexOf('=');
      const prefix = equals === -1 ? argString : argString.slice(0, equals);
      const explicitArg = equals === -1 ? null : argString.slice(equals + 1);
      for (const optionString of this.optionStringActions.keys()) {
        if (optionString.startsWith(prefix)) {
          result.push({ action: this.optionStringActions.get(optionString), optionString, explicitArg });
        }
      }
    } else {
      // Single-dash: either the whole token abbreviates a long option, or its
      // first two characters name a short option carrying an attached value.
      const optionPrefix = argString;
      const shortOptionPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const optionString of this.optionStringActions.keys()) {
        if (optionString === shortOptionPrefix) {
          result.push({
            action: this.optionStringActions.get(optionString),
            optionString,
            explicitArg: shortExplicitArg,
          });
        } else if (optionString.startsWith(optionPrefix)) {
          result.push({ action: this.optionStringActions.get(optionString), optionString, explicitArg: null });
        }
      }
    }
    return result;
  }

  /**
   * @param {string} optionString
   * @param {Action} action
   * @param {string} text
   */
  _convert(optionString, action, text) {
    if (!action.type) return text;
    const converter = TYPE_REGISTRY[action.type];
    try {
      return converter(text);
    } catch (err) {
      if (err instanceof PyValueError) {
        this.error(`argument ${optionString}: invalid ${action.type} value: ${reprString(text)}`);
      }
      throw err;
    }
  }

  /**
   * @param {string[]} [argv] defaults to the real command line
   * @returns {Record<string, unknown>}
   */
  parseArgs(argv) {
    const { namespace, extras } = this.parseKnownArgs(argv);
    if (extras.length) this.error(`unrecognized arguments: ${extras.join(' ')}`);
    return namespace;
  }

  /**
   * @param {string[]} [argv]
   * @returns {{namespace: Record<string, unknown>, extras: string[]}}
   */
  parseKnownArgs(argv) {
    const args = argv ?? process.argv.slice(2);

    /** @type {Record<string, unknown>} */
    const namespace = {};
    /** @type {string[]} */
    const extras = [];
    const seen = new Set();

    let sawDoubleDash = false;
    let index = 0;

    while (index < args.length) {
      const arg = args[index];

      if (!sawDoubleDash && arg === '--') {
        // The first `--` is consumed; everything after it is a value.
        sawDoubleDash = true;
        index += 1;
        continue;
      }

      const optional = sawDoubleDash ? null : this._parseOptional(arg);

      if (optional === null) {
        // No positionals are defined, so any value here is left over.
        extras.push(arg);
        index += 1;
        continue;
      }

      const { action, optionString, explicitArg } = optional;

      if (action === null) {
        extras.push(arg);
        index += 1;
        continue;
      }

      if (action.isHelpAction) {
        if (explicitArg !== null) {
          this.error(`argument ${optionString}: ignored explicit argument ${reprString(explicitArg)}`);
        }
        this.printHelp();
      }

      if (action.nargs === 0) {
        seen.add(action);
        namespace[action.dest] = true;
        index += 1;
        continue;
      }

      let rawValue;
      if (explicitArg !== null) {
        rawValue = explicitArg;
        index += 1;
      } else {
        const next = index + 1 < args.length ? args[index + 1] : undefined;
        const nextIsValue = next !== undefined && this._parseOptional(next) === null;
        if (!nextIsValue) this.error(`argument ${optionString}: expected one argument`);
        rawValue = next;
        index += 2;
      }

      seen.add(action);
      namespace[action.dest] = this._convert(optionString, action, rawValue);
    }

    const missing = this.actions.filter((action) => action.required && !seen.has(action));
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.map((a) => a.name).join(', ')}`);
    }

    for (const action of this.actions) {
      if (!(action.dest in namespace) && !action.isHelpAction) namespace[action.dest] = null;
    }

    return { namespace, extras };
  }
}

