    /** @type {Record<string, unknown>} */
    const namespace = {};
    /** @type {string[]} */
    const extras = [];
    const seen = new Set();

    let sawDoubleDash = false;
    let index = 0;

    while (index < args.length) {
      const arg = args[index];

      if (!sawDoubleDash && arg === '--') {
        // The first `--` is consumed; everything after it is a value.
        sawDoubleDash = true;
        index += 1;
        continue;
      }

      const optional = sawDoubleDash ? null : this._parseOptional(arg);

      if (optional === null) {
        // No positionals are defined, so any value here is left over.
        extras.push(arg);
        index += 1;
        continue;
      }

      const { action, optionString, explicitArg } = optional;

      if (action === null) {
        extras.push(arg);
        index += 1;
        continue;
      }

      if (action.isHelpAction) {
        if (explicitArg !== null) {
          this.error(`argument ${optionString}: ignored explicit argument ${reprString(explicitArg)}`);
        }
        this.printHelp();
      }

      if (action.nargs === 0) {
        seen.add(action);
        namespace[action.dest] = true;
        index += 1;
        continue;
      }

      let rawValue;
      if (explicitArg !== null) {
        rawValue = explicitArg;
        index += 1;
      } else {
        const next = index + 1 < args.length ? args[index + 1] : undefined;
        const nextIsValue = next !== undefined && this._parseOptional(next) === null;
        if (!nextIsValue) this.error(`argument ${optionString}: expected one argument`);
        rawValue = next;
        index += 2;
      }

      seen.add(action);
      namespace[action.dest] = this._convert(optionString, action, rawValue);
    }

    const missing = this.actions.filter((action) => action.required && !seen.has(action));
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.map((a) => a.name).join(', ')}`);
    }

    for (const action of this.actions) {
      if (!(action.dest in namespace) && !action.isHelpAction) namespace[action.dest] = null;
    }

    return { namespace, extras };
  }
}

/** `os.path.basename(sys.argv[0])` */
function defaultProg() {
  const script = process.argv[1] ?? 'prog';
  const parts = script.split(/[\\/]/);
  return parts[parts.length - 1] || script;
}

