/**
 * An insertion-ordered set, standing in for the `SetOrdered` type DeepDiff uses
 * for key bookkeeping. Preserving order is what keeps the reported keys in the
 * order they appear in the source dictionaries rather than sorted as strings.
 */
export class OrderedSet {
  /** @param {Iterable<string>} [items] */
  constructor(items) {
    /** @type {Set<string>} */
    this._items = new Set(items ?? []);
  }

  get size() {
    return this._items.size;
  }

  /** @param {string} item */
  has(item) {
    return this._items.has(item);
  }

  /** `self & other` -- retains this set's order. */
  intersection(other) {
    const result = new OrderedSet();
    for (const item of this._items) if (other.has(item)) result._items.add(item);
    return result;
  }

  /** `self - other` -- retains this set's order. */
  difference(other) {
    const result = new OrderedSet();
    for (const item of this._items) if (!other.has(item)) result._items.add(item);
    return result;
  }

  /** `self | other` -- this set's order, then the newcomers from `other`. */
  union(other) {
    const result = new OrderedSet(this._items);
    for (const item of other) result._items.add(item);
    return result;
  }

  [Symbol.iterator]() {
    return this._items[Symbol.iterator]();
  }
}

