/**
 * Path rendering. DeepDiff labels the compared objects `root` and appends one
 * `[<repr of key>]` segment per level of descent, so a string key `'3'` inside
 * the top-level dict becomes `root['3']`.
 */

import { pyRepr } from '../python/repr.mjs';

/**
 * @param {Array<{kind: 'key'|'index'|'attribute', value: unknown}>} segments
 * @returns {string}
 */
export function formatPath(segments) {
  let path = 'root';
  for (const segment of segments) {
    if (segment.kind === 'attribute') path += `.${segment.value}`;
    else path += `[${pyRepr(segment.value)}]`;
  }
  return path;
}

