/**
 * The intermediate tree DeepDiff builds while walking two objects. Each entry
 * records one difference together with the path at which it was found; the text
 * view is derived from this tree afterwards.
 */

import { formatPath } from './path.mjs';

export class DiffLevel {
  /**
   * @param {unknown} t1 the value on the left-hand side
   * @param {unknown} t2 the value on the right-hand side
   * @param {Array<{kind: string, value: unknown}>} segments path from the root
   */
  constructor(t1, t2, segments = []) {
    this.t1 = t1;
    this.t2 = t2;
    this.segments = segments;
  }

  /**
   * Descend into a mapping key.
   *
   * @param {string} key
   * @param {unknown} t1
   * @param {unknown} t2
   */
  child(key, t1, t2) {
    return new DiffLevel(t1, t2, [...this.segments, { kind: 'key', value: key }]);
  }

  path() {
    return formatPath(this.segments);
  }
}

export class TreeResult {
  constructor() {
    /** @type {Map<string, DiffLevel[]>} */
    this._entries = new Map();
  }

  /**
   * @param {string} reportType
   * @param {DiffLevel} level
   */
  add(reportType, level) {
    const bucket = this._entries.get(reportType);
    if (bucket) bucket.push(level);
    else this._entries.set(reportType, [level]);
  }

  /** @param {string} reportType */
  get(reportType) {
    return this._entries.get(reportType) ?? [];
  }

  has(reportType) {
    return (this._entries.get(reportType) ?? []).length > 0;
  }
}

