/**
 * The comparison walk itself.
 */

import { PyDict } from '../python/dict.mjs';
import { pyTypeName } from '../python/repr.mjs';
import { OrderedSet } from './ordered_set.mjs';
import { DiffLevel, TreeResult } from './tree.mjs';
import { NOT_PRESENT, THRESHOLD_TO_DIFF_DEEPER } from './constants.mjs';

export class DiffEngine {
  /** @param {{thresholdToDiffDeeper?: number}} [options] */
  constructor(options = {}) {
    this.thresholdToDiffDeeper = options.thresholdToDiffDeeper ?? THRESHOLD_TO_DIFF_DEEPER;
    this.tree = new TreeResult();
  }

  /**
   * @param {unknown} t1
   * @param {unknown} t2
   */
  run(t1, t2) {
    this._diff(new DiffLevel(t1, t2));
    return this.tree;
  }

  /** @param {DiffLevel} level */
  _diff(level) {
    const { t1, t2 } = level;

    // `t1 is t2` -- identical objects can hold no differences.
    if (t1 === t2) return;

    if (pyTypeName(t1) !== pyTypeName(t2)) {
      this.tree.add('type_changes', level);
      return;
    }

    if (t1 instanceof PyDict) {
      this._diffDict(level);
      return;
    }

    if (!pyEquals(t1, t2)) this.tree.add('values_changed', level);
  }

  /** @param {DiffLevel} level */
  _diffDict(level) {
    /** @type {PyDict} */
    const t1 = level.t1;
    /** @type {PyDict} */
    const t2 = level.t2;

    const t1Keys = new OrderedSet(t1.keys());
    const t2Keys = new OrderedSet(t2.keys());

    const intersect = t2Keys.intersection(t1Keys);
    const added = t2Keys.difference(intersect);
    const removed = t1Keys.difference(intersect);

    // Too little overlap to be worth descending: report the mappings themselves
    // as a single changed value instead of enumerating every key.
    if (this.thresholdToDiffDeeper > 0) {
      const union = t1Keys.union(t2Keys);
      if (union.size > 1 && intersect.size / union.size < this.thresholdToDiffDeeper) {
        this.tree.add('values_changed', level);
        return;
      }
    }

    for (const key of added) {
      this.tree.add('dictionary_item_added', level.child(key, NOT_PRESENT, t2.get(key)));
    }
    for (const key of removed) {
      this.tree.add('dictionary_item_removed', level.child(key, t1.get(key), NOT_PRESENT));
    }
    for (const key of intersect) {
      this._diff(level.child(key, t1.get(key), t2.get(key)));
    }
  }
}

/** Structural equality with Python's `==` semantics for the supported types. */
export function pyEquals(a, b) {
  if (a instanceof PyDict && b instanceof PyDict) {
    if (a.size !== b.size) return false;
    for (const [key, value] of a.entries()) {
      if (!b.has(key)) return false;
      if (!pyEquals(value, b.get(key))) return false;
    }
    return true;
  }
  return a === b;
}

