/**
 * Turns the difference tree into the flat, printable mapping that DeepDiff
 * exposes as its default (text) view.
 *
 * Only the categories reachable from this program are given a real converter;
 * the rest fall back to a bare list of paths, which is what DeepDiff does for
 * them too.
 */

import { PyDict } from '../python/dict.mjs';
import { pyRepr, pyTypeName } from '../python/repr.mjs';
import { REPORT_KEY_ORDER } from './constants.mjs';

/** Categories rendered as a list of paths. */
const PATH_LIST_CATEGORIES = new Set([
  'dictionary_item_added',
  'dictionary_item_removed',
  'iterable_item_added',
  'iterable_item_removed',
  'attribute_added',
  'attribute_removed',
  'set_item_added',
  'set_item_removed',
]);

/**
 * @param {import('./tree.mjs').TreeResult} tree
 * @returns {PyDict}
 */
export function buildTextResult(tree) {
  const result = new PyDict();

  for (const category of REPORT_KEY_ORDER) {
    const levels = tree.get(category);
    if (!levels.length) continue;

    if (PATH_LIST_CATEGORIES.has(category)) {
      result.set(category, levels.map((level) => level.path()));
      continue;
    }

    if (category === 'values_changed') {
      const changes = new PyDict();
      for (const level of levels) {
        changes.set(
          level.path(),
          new PyDict([
            ['new_value', level.t2],
            ['old_value', level.t1],
          ]),
        );
      }
      result.set(category, changes);
      continue;
    }

    if (category === 'type_changes') {
      const changes = new PyDict();
      for (const level of levels) {
        changes.set(
          level.path(),
          new PyDict([
            ['old_type', Symbol(`<class '${pyTypeName(level.t1)}'>`)],
            ['new_type', Symbol(`<class '${pyTypeName(level.t2)}'>`)],
            ['old_value', level.t1],
            ['new_value', level.t2],
          ]),
        );
      }
      result.set(category, changes);
      continue;
    }

    result.set(category, levels.map((level) => level.path()));
  }

  return result;
}

/**
 * `repr()` of the text view. DeepDiff's result subclasses `dict`, so printing it
 * yields a plain dictionary repr.
 *
 * @param {PyDict} textResult
 */
export function formatTextResult(textResult) {
  return pyRepr(textResult);
}

