/**
 * Node.js port of dataset/deepdiff/test12.py
 *
 *   import argparse
 *   from deepdiff import DeepDiff
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--a', type=int, required=True)
 *   ... --b, --c, --d ...
 *   args = parser.parse_args()
 *
 *   obj1 = {str(i): i * args.a for i in range(args.b)}
 *   obj2 = {str(i): i * args.c for i in range(args.d)}
 *   obj3 = {k: v * 2 for k, v in obj1.items()}
 *   obj4 = {k: v + 10 for k, v in obj2.items()}
 *
 *   then prints DeepDiff over ten pairs of those dictionaries.
 */

import { ArgumentParser } from './lib/cli/argparse.mjs';
import { SystemExit } from './lib/cli/errors.mjs';
import { PyDict, dictFromRange } from './lib/python/dict.mjs';
import { DeepDiff } from './lib/deepdiff/index.mjs';

export function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { type: 'int', required: true });
  parser.addArgument('--b', { type: 'int', required: true });
  parser.addArgument('--c', { type: 'int', required: true });
  parser.addArgument('--d', { type: 'int', required: true });
  const args = parser.parseArgs();

  const obj1 = dictFromRange(args.a === null ? 0n : args.b, (i) => i * args.a);
  const obj2 = dictFromRange(args.c === null ? 0n : args.d, (i) => i * args.c);
  const obj3 = obj1.mapValues((v) => v * 2n);
  const obj4 = obj2.mapValues((v) => v + 10n);

  const r1 = DeepDiff(obj1, obj2); // 比较两个字典
  console.log(String(r1));
  const r2 = DeepDiff(obj2, obj3); // 比较obj2和obj3
  console.log(String(r2));
  const r3 = DeepDiff(obj3, obj4); // 比较obj3和obj4
  console.log(String(r3));
