#!/usr/bin/env node
// Differential tester: runs the Python executable and the Node port with the
// same argv and compares stdout, stderr and exit code byte-for-byte.
import { spawn } from 'node:child_process';

const EXE = '/workspace/dataset/test12_executable';
const NODE_ENTRY = '/output/test12.mjs';
const PROG_PY = 'test12_executable';
const PROG_JS = 'test12.mjs';

function run(cmd, argv) {
  return new Promise((resolve) => {
    const child = spawn(cmd[0], [...cmd.slice(1), ...argv], { stdio: ['ignore', 'pipe', 'pipe'] });
    const out = [];
    const err = [];
    child.stdout.on('data', (c) => out.push(c));
    child.stderr.on('data', (c) => err.push(c));
    child.on('close', (code) =>
      resolve({ code, out: Buffer.concat(out).toString('utf8'), err: Buffer.concat(err).toString('utf8') }));
  });
}

// The program name legitimately differs (argparse uses argv[0]'s basename), so
// normalize it before comparing error/help text.
const normalize = (s, prog) => s.split(prog).join('<PROG>');

async function check(argv) {
  const [py, js] = await Promise.all([run([EXE], argv), run(['node', NODE_ENTRY], argv)]);
  const diffs = [];
  if (py.code !== js.code) diffs.push(`exit: py=${py.code} js=${js.code}`);
  if (normalize(py.out, PROG_PY) !== normalize(js.out, PROG_JS)) diffs.push('stdout');
  if (normalize(py.err, PROG_PY) !== normalize(js.err, PROG_JS)) diffs.push('stderr');
  return { argv, diffs, py, js };
}

async function pool(items, limit, fn) {
  const results = [];
  let next = 0;
  const workers = Array.from({ length: limit }, async () => {
    while (next < items.length) {
      const i = next++;
      results[i] = await fn(items[i]);
    }
  });
  await Promise.all(workers);
  return results;
}

const cases = [];
const group = process.argv[2] ?? 'all';

if (group === 'grid' || group === 'all') {
  for (let b = 0; b <= 14; b++) for (let d = 0; d <= 14; d++) cases.push(['--a', '1', '--b', String(b), '--c', '1', '--d', String(d)]);
}
if (group === 'values' || group === 'all') {
  const as = ['0', '1', '2', '-1', '-3', '7', '99999999999999999999', '-12345678901234567890123'];
  for (const a of as) for (const c of as) cases.push(['--a', a, '--b', '5', '--c', c, '--d', '7']);
  for (const a of as) cases.push(['--a', a, '--b', '3', '--c', '2', '--d', '3']);
}
if (group === 'ratios' || group === 'all') {
  const pairs = [[1,3],[1,4],[2,6],[2,7],[3,9],[3,10],[4,12],[4,13],[5,15],[5,16],[10,30],[10,31],[33,100],[32,100],[33,99],[34,100],[0,1],[1,0],[0,2],[2,0],[7,21],[7,22],[11,33],[11,34],[1,1],[100,100],[99,100],[100,99],[-5,3],[3,-5],[-5,-7],[50,17],[17,50],[16,50],[50,16]];
  for (const [b, d] of pairs) cases.push(['--a', '3', '--b', String(b), '--c', '2', '--d', String(d)]);
}
if (group === 'cli' || group === 'all') {
  cases.push(
    [], ['--help'], ['-h'], ['--h'], ['--he'],
    ['--a', '1'], ['--a', '1', '--b', '2'], ['--a', '1', '--b', '2', '--c', '3'],
    ['--a=1', '--b=2', '--c=3', '--d=4'],
    ['--a', 'x', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '1.5', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '0x10', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '  12  ', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '\t5\n', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '+7', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '-0', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '-7', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '1_0_0', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '_1', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '1_', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '1__0', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '١٢', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '٣', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '𝟛', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '１２', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '１_２', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', ' 5', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', ' 5', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '　5', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', ' 5', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '5', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '﻿5', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '5', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '²', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '- 5', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '5 ', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', "it's", '--b', '2', '--c', '3', '--d', '4'],
    ['--a', 'say "hi"', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', 'a\'b"c', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', 'a\nb', '--b', '2', '--c', '3', '--d', '4'],
    ['--a'], ['--a', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '1', '--a', '7', '--b', '2', '--c', '3', '--d', '4'],
    ['--a', '1', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
    ['--a', '1', '--b', '2', '--c', '3', '--d', '4', 'extra'],
    ['--a', '1', '--b', '2', '--c', '3', '--d', '4', '--', 'x'],
    ['--e', '5'], ['-x'], ['-'], ['--'],
    ['--a', '1', '--b', '2', '--c', '3', '--d', '4', '--help'],
    ['--help', '--a', 'x'],
    ['-h5'], ['--a5'], ['--help=1'],
  );
}

const results = await pool(cases, 8, check);
let bad = 0;
for (const r of results) {
  if (r.diffs.length) {
    bad++;
    console.log('MISMATCH', JSON.stringify(r.argv), '->', r.diffs.join(','));
    console.log('  py exit', r.py.code, 'out', JSON.stringify(r.py.out.slice(0, 300)), 'err', JSON.stringify(r.py.err.slice(0, 300)));
    console.log('  js exit', r.js.code, 'out', JSON.stringify(r.js.out.slice(0, 300)), 'err', JSON.stringify(r.js.err.slice(0, 300)));
  }
}
console.log(`\n[${group}] ${results.length - bad}/${results.length} identical, ${bad} mismatched`);
process.exitCode = bad ? 1 : 0;

